#pragma once
#include "kstationFlashStateTask.h"
namespace kstation {
class StartupAdcStartTask final {
public:enum class Stage{RetainValue,RetainScratch,ReadGroup,CompareGroup,SelectBusy,ClearGroup,WriteGroup,Mux,Control,WriteControl,RestoreScratch,RestoreValue,Return,Complete};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaiting()const{return waiting_;}void resume(){waiting_=false;}unsigned nextClocks(const FlashCredits&c)const{if(waiting_||complete())return 0;switch(stage_){case Stage::RetainValue:case Stage::RetainScratch:return c.pushWord;case Stage::ReadGroup:return 9+c.read;case Stage::WriteGroup:return 9+c.write;case Stage::WriteControl:return 3+c.write;case Stage::Mux:return c.shortCall;case Stage::RestoreScratch:case Stage::RestoreValue:return c.popWord;case Stage::Return:return c.ret;default:return 3;}}template<class R,class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,R&&read,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::ReadGroup:group_=uint8_t(read());break;case Stage::SelectBusy:if(group_<=28)next=Stage::RestoreScratch;break;case Stage::WriteGroup:write(false,0);break;case Stage::Mux:waiting_=true;break;case Stage::WriteControl:write(true,0x73);break;default:break;}stage_=next;return cost;}
private:Stage stage_=Stage::RetainValue;uint8_t group_=0;bool waiting_=false;};
class StartupAdcSnapshotTask final {
public:enum class Stage{RetainPointer,RetainValue,Bind,Count,Arm,Read,WriteSample,WriteArmed,Advance,Decrement,Repeat,RestoreValue,RestorePointer,Return,Complete};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}unsigned index()const{return index_;}unsigned nextClocks(const FlashCredits&c)const{switch(stage_){case Stage::RetainPointer:case Stage::RetainValue:return c.pushLong;case Stage::Bind:return 9;case Stage::Read:return 6+c.read;case Stage::WriteSample:return 3+c.write;case Stage::WriteArmed:return 6+c.write;case Stage::RestoreValue:case Stage::RestorePointer:return c.popLong;case Stage::Return:return c.ret;case Stage::Complete:return 0;default:return 3;}}template<class R,class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,R&&read,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::Read:value_=uint16_t(read(index_));break;case Stage::WriteSample:write(false,index_,value_);break;case Stage::WriteArmed:write(true,index_,1);break;case Stage::Advance:++index_;break;case Stage::Repeat:if(index_<32)next=Stage::Read;break;default:break;}stage_=next;return cost;}
private:Stage stage_=Stage::RetainPointer;unsigned index_=0;uint16_t value_=0;};
class StartupAdcQueueTask final {
public:enum class Stage{Retain,Clear,WriteProducer,WriteConsumer,Restore,Return,Complete};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}unsigned nextClocks(const FlashCredits&c)const{switch(stage_){case Stage::Retain:return c.pushWord;case Stage::WriteProducer:case Stage::WriteConsumer:return 9+c.write;case Stage::Restore:return c.popWord;case Stage::Return:return c.ret;case Stage::Complete:return 0;default:return 3;}}template<class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;if(stage_==Stage::WriteProducer||stage_==Stage::WriteConsumer)write(stage_==Stage::WriteProducer,0);stage_=Stage(unsigned(stage_)+1);return cost;}
private:Stage stage_=Stage::Retain;};
class StartupAdcTask final {
public:enum class Stage{IdleValue,WriteIdle,Passes,RetainPass,StartGroup,RetainDelay,Settling,RetainInner,Delay,DecrementDelay,RepeatDelay,RestoreInner,DecrementSettling,RepeatSettling,RestoreDelay,ReadGroup,CompareGroup,WaitGroup,RestorePass,DecrementPass,RepeatPass,Snapshot,ClearQueue,Return,Complete};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaiting()const{return waiting_;}void resume(){waiting_=false;}unsigned nextClocks(const FlashCredits&c)const{if(waiting_||complete())return 0;switch(stage_){case Stage::WriteIdle:return 9+c.write;case Stage::RetainPass:case Stage::RetainDelay:case Stage::RetainInner:return c.pushWord;case Stage::StartGroup:case Stage::Snapshot:case Stage::ClearQueue:return c.call;case Stage::Settling:case Stage::Delay:return 6;case Stage::RestoreInner:case Stage::RestoreDelay:case Stage::RestorePass:return c.popWord;case Stage::ReadGroup:return 9+c.read;case Stage::Return:return c.ret;default:return 3;}}template<class R,class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,R&&read,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::WriteIdle:write(32);break;case Stage::Passes:passes_=16;break;case Stage::StartGroup:case Stage::Snapshot:case Stage::ClearQueue:waiting_=true;break;case Stage::Settling:settling_=1;break;case Stage::Delay:delay_=2663;break;case Stage::DecrementDelay:--delay_;break;case Stage::RepeatDelay:if(delay_)next=Stage::DecrementDelay;break;case Stage::DecrementSettling:--settling_;break;case Stage::RepeatSettling:if(settling_)next=Stage::RetainInner;break;case Stage::ReadGroup:group_=uint8_t(read());break;case Stage::WaitGroup:if(group_<=28)next=Stage::ReadGroup;break;case Stage::DecrementPass:--passes_;break;case Stage::RepeatPass:if(passes_)next=Stage::RetainPass;break;default:break;}stage_=next;return cost;}
private:Stage stage_=Stage::IdleValue;unsigned passes_=0,settling_=0,delay_=0;uint8_t group_=0;bool waiting_=false;};
}
